import stylesText from './nutrition-edit.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';

const styles = cssStyleSheet(stylesText);
import { MEAL_TYPES, dateAndTimeToInstant, instantToHHMM } from '@motivation/shared';
import type { ConsumptionEntry, FoodItem, MealType, NewConsumptionEntry, NutritionSource } from '@motivation/shared';
import { getAppTimeZone } from '../../../services/app-timezone.service.js';
import { HealthService } from '../../../services/health.service.js';
import { whileBusy } from '../../../utils/in-flight.js';
import { HEALTH_EVENTS } from '../health-events.js';
import { consumptionEntryToFormData } from '../food-serving-form/food-serving-form.types.js';
import '../food-serving-form/food-serving-form.component.js';
import '../photo-controls/photo-controls.component.js';
import type { FoodServingForm } from '../food-serving-form/food-serving-form.component.js';
import type { PhotoControls } from '../photo-controls/photo-controls.component.js';

const template = document.createElement('template');
template.innerHTML = `
    <div class="edit-container">
        <div class="edit-header">
            <div class="edit-header-text">
                <h3>Edit Entry</h3>
                <span class="source-badge" id="source-badge"></span>
            </div>
        </div>

        <!-- Story 355: the food's photo, not the entry's — it shows wherever the food does. -->
        <photo-controls id="photo" scope="food"></photo-controls>

        <input type="text" id="food-name" class="food-name-input" placeholder="Food name" readonly>

        <food-serving-form id="serving-form" editable></food-serving-form>

        <div class="form-row">
            <div class="form-group">
                <label for="meal-type">Meal</label>
                <select id="meal-type" class="form-select">
                    ${MEAL_TYPES.map(m => `<option value="${m}">${m}</option>`).join('\n                    ')}
                </select>
            </div>
            <div class="form-group">
                <label for="date">Date</label>
                <input type="date" id="date" class="form-input" required>
            </div>
            <div class="form-group">
                <label for="consumed-time">Time</label>
                <input type="time" id="consumed-time" class="form-input">
            </div>
        </div>

        <div class="action-buttons">
            <button class="btn-delete" id="btn-delete">Delete</button>
            <button class="btn-save" id="btn-save">Save</button>
        </div>
    </div>
`;

/**
 * Keyed by `NutritionSource` rather than `string`, so adding a source without a
 * label here is a compile error instead of a badge that reads `label_photo`.
 * That is exactly how story 338 nearly shipped: the `?? item.source` fallback
 * below degrades quietly enough that nothing fails.
 */
const SOURCE_LABELS: Record<NutritionSource, string> = {
    manual: 'Manual',
    openfoodfacts: 'Open Food Facts',
    ai_estimate: 'AI Estimate',
    mfp_import: 'MFP Import',
    label_photo: 'Label Photo',
};

/**
 * Edit a consumption entry. The food_item is shown for context but cannot be
 * changed here — to log a different food, the user deletes this entry and
 * creates a new one. Editable fields: meal_type, date, amount, and per-entry
 * macro overrides. The one exception is the food's photo (story 355), saved
 * straight to the food item, independent of Save.
 */
export class NutritionEdit extends HTMLElement {
    private _entry: ConsumptionEntry | null = null;
    private _foodItem: FoodItem | null = null;
    /** Story 371: the returned promise (if any) holds Save/Delete disabled until it settles. */
    private _onSave: ((id: string, updates: Partial<NewConsumptionEntry>) => unknown) | null = null;
    private _onDelete: ((id: string) => unknown) | null = null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        // <photo-controls> would only upgrade once this editor is connected (story 380's reason).
        customElements.upgrade(shadow);

        // Story 403: the row exists, so the photo is saved on the food at once and queues offline.
        const photo = shadow.getElementById('photo') as PhotoControls;
        photo.addEventListener(HEALTH_EVENTS.PHOTO_PICKED, (e) => { e.detail.respondWith = this.saveFoodImage(e.detail.image_path); });
        photo.addEventListener(HEALTH_EVENTS.PHOTO_REMOVED, (e) => { e.detail.respondWith = this.saveFoodImage(null); });
        photo.addEventListener(HEALTH_EVENTS.PHOTO_LANDED, (e) => {
            if (this._foodItem) this._foodItem = { ...this._foodItem, image_path: e.detail.image_path };
        });
    }

    connectedCallback() {
        const shadow = this.shadowRoot!;
        // Story 371: each held until its work settles, so a double tap acts once.
        const save = shadow.getElementById('btn-save') as HTMLButtonElement;
        const del = shadow.getElementById('btn-delete') as HTMLButtonElement;
        save.addEventListener('click', () => void whileBusy(save, () => this.handleSave()));
        del.addEventListener('click', () => void whileBusy(del, () => this.handleDelete()));

        if (this._entry && this._foodItem) {
            this.populateForm();
        }
    }

    set onSave(handler: (id: string, updates: Partial<NewConsumptionEntry>) => unknown) {
        this._onSave = handler;
    }

    set onDelete(handler: (id: string) => unknown) {
        this._onDelete = handler;
    }

    set entry(val: ConsumptionEntry) {
        this._entry = val;
        if (this.isConnected && this._foodItem) {
            this.populateForm();
        }
    }

    get entry(): ConsumptionEntry | null {
        return this._entry;
    }

    set foodItem(val: FoodItem) {
        this._foodItem = val;
        if (this.isConnected && this._entry) {
            this.populateForm();
        }
    }

    private populateForm(): void {
        const e = this._entry;
        const item = this._foodItem;
        if (!e || !item) return;
        const shadow = this.shadowRoot!;

        shadow.getElementById('source-badge')!.textContent = SOURCE_LABELS[item.source] ?? item.source;
        (shadow.getElementById('photo') as PhotoControls).show({
            localRef: item.id,
            path: item.image_path ?? null,
            alt: item.display_name,
            editable: true,
        });
        (shadow.getElementById('food-name') as HTMLInputElement).value = item.display_name;
        (shadow.getElementById('meal-type') as HTMLSelectElement).value = e.meal_type;
        (shadow.getElementById('date') as HTMLInputElement).value = e.date;
        // Eaten-at wall-clock in the app zone; empty when unstamped (story
        // 260) — an unstamped legacy row shows an empty field, not "now".
        (shadow.getElementById('consumed-time') as HTMLInputElement).value =
            e.consumed_at ? instantToHHMM(e.consumed_at, getAppTimeZone()) : '';

        const form = shadow.getElementById('serving-form') as FoodServingForm;
        form.data = consumptionEntryToFormData(e, item);
    }

    /** The photo is the food's, not the entry's: a PATCH of the food, independent of Save. */
    private async saveFoodImage(imagePath: string | null): Promise<void> {
        const item = this._foodItem;
        if (!item) throw new Error('No food is loaded to put the photo on');
        this._foodItem = await HealthService.updateFoodItem(item.id, { image_path: imagePath });
    }

    private handleSave(): unknown {
        if (!this._entry || !this._onSave) return;
        const shadow = this.shadowRoot!;

        // Story 371 (pwa-nutrition-11): a cleared date saved as '', and the entry
        // dropped out of every day. The field is required.
        const dateInput = shadow.getElementById('date') as HTMLInputElement;
        if (!dateInput.value) {
            dateInput.reportValidity();
            return;
        }

        const form = shadow.getElementById('serving-form') as FoodServingForm;
        const values = form.getCurrentValues();
        if (!values) return; // the form flags the amount
        // The entry's own snapshot, scaled — an unknown macro stays null (story 368).
        const { servingAmount, serving } = values;

        const date = dateInput.value;
        // A set time anchors on the (possibly edited) date in the app zone; a
        // cleared field clears the stamp (story 260).
        const time = (shadow.getElementById('consumed-time') as HTMLInputElement).value;
        const updates: Partial<NewConsumptionEntry> = {
            meal_type: (shadow.getElementById('meal-type') as HTMLSelectElement).value as MealType,
            date,
            amount: servingAmount,
            consumed_at: time ? dateAndTimeToInstant(date, time, getAppTimeZone()) : null,
            ...serving,
        };

        return this._onSave(this._entry.id, updates);
    }

    private handleDelete(): unknown {
        if (!this._entry || !this._onDelete) return;
        const name = this._foodItem?.display_name ?? 'this entry';
        if (!confirm(`Delete "${name}"?`)) return;
        return this._onDelete(this._entry.id);
    }
}

if (!customElements.get('nutrition-edit')) {
    customElements.define('nutrition-edit', NutritionEdit);
}
